     2232:                 xmlDocPtr doc = (xmlDocPtr) cur;
     2233: 
     2234:                 res = doc->URL;
     2235:                 break;
     2236:             }
     2237:         case XML_ATTRIBUTE_NODE:{
     2238:                 xmlAttrPtr attr = (xmlAttrPtr) cur;
     2239: 
     2240:                 res = attr->name;
     2241:                 break;
     2242:             }
     2243:         case XML_NAMESPACE_DECL:{
     2244:                 xmlNsPtr ns = (xmlNsPtr) cur;
     2245: 
     2246:                 res = ns->prefix;
     2247:                 break;
     2248:             }
     2249:         default:
     2250:             res = cur->name;
     2251:             break;
     2252:     }
